INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT 'f9d039cd-9590-5ec2-a52f-906c89fe7a0e', c.id, 'a/an + singular countable N | the + specific N | Ø + uncountable/plural N', 'noun_phrase', 'Distinguish countable vs. uncountable nouns and first-mention vs. specific reference.', 'Danh từ đếm được số ít bắt buộc phải có mạo từ (a/an/the) hoặc từ hạn định (my/this) đứng trước. Dùng a/an khi nhắc lần đầu, dùng the khi cả người nói và người nghe đều biết rõ đối tượng.', 'Không để trống danh từ đếm được số ít (nói ''I have car'' là sai -> ''I have a car''); không thêm -s hoặc dùng a/an với danh từ không đếm được như water, rice, advice, information, money, luggage.', '[{"label": "determiner", "role": "reference_type", "required": true, "examples": ["a", "an", "the"]}, {"label": "noun", "role": "entity_head", "required": true, "examples": ["ticket", "apple", "station"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:articles-countability-core' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '7a792361-677b-5f18-a716-59b1b5277fa2', c.id, 'S + am/is/are + complement', 'copular_clause', 'Link a subject to an identity, state, description, or location.', 'Động từ be thay đổi theo chủ ngữ: I đi với am; he/she/it và danh từ số ít đi với is; you/we/they và danh từ số nhiều đi với are. Be nối chủ ngữ với danh tính, tính chất, trạng thái hoặc nơi chốn.', 'Không bỏ am/is/are như trong câu tiếng Việt; không dùng do/does trước be; chọn đúng dạng be theo chủ ngữ.', '[{"label": "S", "role": "subject", "required": true, "examples": ["I", "she", "the station"]}, {"label": "am/is/are", "role": "finite_copula", "required": true, "examples": ["am", "is", "are"]}, {"label": "complement", "role": "subject_complement", "required": true, "examples": ["a student", "tired", "at home"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:be-basic' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '6dabc029-a680-542c-be18-281ddae94c72', c.id, 'S + can/can''t + base verb | Can + S + base verb?', 'modality', 'Express basic ability, possibility, or make simple everyday requests.', 'Động từ khuyết thiếu can giữ nguyên với mọi chủ ngữ và theo sau luôn là động từ nguyên mẫu không ''to''.', 'Không thêm -s vào can khi chủ ngữ là he/she/it; không dùng ''can to V''.', '[{"label": "S + can/can''t", "role": "modal_subject", "required": true, "examples": ["I can", "She can''t", "Can you"]}, {"label": "base verb", "role": "action_potential", "required": true, "examples": ["swim", "help me", "pay by card"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:can-ability-requests' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '6ec8e024-9188-5417-8de7-3a79e27c7152', c.id, 'S + be + adjective-er + than + NP | S + be + more + adjective + than + NP', 'comparison', 'Compare one person, thing, place, or option with another.', 'Dùng tính từ ngắn với -er và tính từ dài với more, rồi dùng than để nêu đối tượng được so sánh. Một số tính từ có dạng bất quy tắc như good → better.', 'Không dùng đồng thời more và -er; than là từ nối so sánh, khác với then; kiểm tra dạng bất quy tắc trước khi thêm -er.', '[{"label": "S + be", "role": "subject_and_copula", "required": true, "examples": ["This hotel is"]}, {"label": "comparative adjective", "role": "comparison_property", "required": true, "examples": ["cheaper", "more convenient", "better"]}, {"label": "than + NP", "role": "comparison_target", "required": true, "examples": ["than the other one"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:comparatives-core' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT 'd8e126f6-c26c-504e-988a-c0cbb8f5295e', c.id, 'Although / Even though + S + V, S + V | Despite / In spite of + NP/V-ing, S + V', 'adverbial_clause', 'Express contrast or concession between an unexpected condition and the actual result.', 'Although / Even though đi với một mệnh đề đầy đủ (S + V); còn Despite / In spite of đi với cụm danh từ hoặc V-ing (Despite the heavy rain...).', 'Tuyệt đối KHÔNG dùng ''Although..., but...'' trong cùng một câu tiếng Anh (trong tiếng Việt luôn nói ''Mặc dù... nhưng...'', nhưng trong tiếng Anh chỉ được dùng Although HOẶC but, không dùng cả hai). Ngoài ra không dùng ''despite of''.', '[{"label": "concessive marker + complement", "role": "unexpected_circumstance", "required": true, "examples": ["Although the traffic was heavy", "Despite the short deadline"]}, {"label": "main clause (no ''but'')", "role": "actual_outcome", "required": true, "examples": ["we arrived on time", "the team delivered high quality work"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:contrast-clauses-although-despite' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '0a83710b-73cb-51a9-93ff-3768254a5477', c.id, 'this/these + N (near) | that/those + N (far)', 'determiner_phrase', 'Point to people or things that are near or far in space or time.', 'Dùng this (số ít) và these (số nhiều) cho người/vật ở gần; dùng that (số ít) và those (số nhiều) cho người/vật ở xa.', 'Người Việt thường quên đổi sang these/those khi danh từ là số nhiều, hoặc phát âm giống nhau giữa this (/ðɪs/) và these (/ðiːz/).', '[{"label": "demonstrative", "role": "proximity_number_marker", "required": true, "examples": ["this", "that", "these", "those"]}, {"label": "noun / predicate", "role": "identified_referent", "required": true, "examples": ["book is mine", "chairs are free"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:demonstratives-this-that' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT 'c9a9f9c7-d334-5e62-87b2-beed9afb2f2a', c.id, 'If + present simple, S + will + base verb', 'conditional_clause', 'Describe a realistic future condition and its likely result.', 'Mệnh đề if nêu điều kiện có khả năng xảy ra và dùng hiện tại đơn; mệnh đề kết quả thường dùng will + động từ nguyên mẫu. Có thể đổi thứ tự hai mệnh đề mà không đổi nghĩa chính.', 'Thông thường không dùng will trong mệnh đề if; sau will dùng động từ nguyên mẫu không to; dùng dấu phẩy khi mệnh đề if đứng trước.', '[{"label": "if-clause", "role": "realistic_condition", "required": true, "examples": ["If it rains"]}, {"label": "result subject", "role": "result_subject", "required": true, "examples": ["we"]}, {"label": "will + base verb", "role": "likely_result", "required": true, "examples": ["will stay"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:first-conditional-core' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT 'b050ef23-ae14-5c75-bfa5-eb21e737dc38', c.id, 'S + always/usually/often/sometimes/never + V | S + be + adverb', 'adverbial_placement', 'Express how often an action happens in daily routines.', 'Trạng từ tần suất đứng TRƯỚC động từ thường (I usually walk) nhưng đứng SAU động từ to be (She is always on time).', 'Không dùng ''never'' chung với ''don''t'' trong cùng một mệnh đề (tránh phủ định kép ''I don''t never go'' -> ''I never go'').', '[{"label": "subject (+ be)", "role": "clause_subject", "required": true, "examples": ["I", "He is"]}, {"label": "frequency adverb", "role": "frequency_modifier", "required": true, "examples": ["usually", "always", "often", "never"]}, {"label": "main predicate", "role": "routine_event", "required": true, "examples": ["eat breakfast at seven", "on time"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:frequency-adverbs-order' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT 'a36b8c9d-2e41-5a37-8b80-4e991fb6c6e1', c.id, 'V1 (enjoy/finish/avoid/suggest) + V-ing | V1 (decide/plan/want/promise) + to + V', 'verb_complementation', 'Chain a second verb after a main verb or preposition using the required -ing or to-infinitive form.', 'Một số động từ bắt buộc theo sau bởi V-ing (enjoy, finish, avoid, mind, suggest, practice); một số bắt buộc theo sau bởi to + V (want, need, decide, plan, hope, offer). Sau mọi giới từ (in, on, at, for, about, without, before, after) động từ luôn ở dạng V-ing.', 'Không ghép 2 động từ nguyên mẫu liền nhau kiểu tiếng Việt (''enjoy read book'' -> ''enjoy reading books''; ''decide take bus'' -> ''decide to take the bus'').', '[{"label": "matrix verb / preposition", "role": "complement_selector", "required": true, "examples": ["enjoy", "finished", "decided", "interested in"]}, {"label": "V-ing or to + V", "role": "non_finite_clause", "required": true, "examples": ["reading short stories", "to change the plan", "learning new words"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:gerunds-infinitives-core' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT 'ba522b9f-39bb-558a-bfaa-5f1dca66fcca', c.id, 'S + am/is/are + going to + base verb', 'tense_aspect', 'Talk about prior future intentions, plans, or predictions based on visible present evidence.', 'Dùng ''be going to + V'' khi kế hoạch đã được quyết định từ trước lúc nói, hoặc khi nhìn thấy dấu hiệu rõ ràng sắp xảy ra (Look at the dark clouds — it is going to rain).', 'Không bỏ động từ to be (am/is/are) trước ''going to''; dùng ''will'' cho quyết định nảy ra tức thì ngay lúc nói, còn ''be going to'' cho kế hoạch đã định sẵn.', '[{"label": "S + am/is/are going to", "role": "planned_future_marker", "required": true, "examples": ["We are going to", "She is going to"]}, {"label": "base verb phrase", "role": "intended_action", "required": true, "examples": ["visit Da Nang next month", "call the clinic"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:going-to-future-plans' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '5c127210-dd1a-58fa-9753-58b57a4117d8', c.id, 'Base verb + object | Please + base verb | Don''t + base verb', 'clause_structure', 'Give clear instructions, directions, polite requests, or warnings.', 'Câu mệnh lệnh bắt đầu trực tiếp bằng động từ nguyên mẫu (không có chủ ngữ You). Thêm Please để lịch sự hơn và dùng Don''t + V nguyên mẫu cho câu mệnh lệnh phủ định.', 'Không dùng ''No + V'' hoặc ''Not + V'' ở đầu câu; với tính từ phải có ''Be'' đứng trước (Be careful, không nói Careful!).', '[{"label": "(Please / Don''t)", "role": "politeness_or_negation", "required": false, "examples": ["Please", "Don''t"]}, {"label": "base verb phrase", "role": "directed_action", "required": true, "examples": ["open your book", "forget your key", "be quiet"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:imperatives-basic' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '6e552e17-6135-53ea-b167-1359f46150cb', c.id, 'Could you tell me / Do you know + Wh-word / if + S + V?', 'clause_structure', 'Ask questions more politely in workplace, travel, and customer-service situations.', 'Sau cụm mở đầu lịch sự (''Could you tell me...'', ''Do you know...'', ''I was wondering...''), phần mệnh đề phía sau giữ trật tự câu trần thuật (S + V) chứ không đảo trợ động từ.', 'Với câu hỏi Yes/No chuyển sang gián tiếp, nhớ thêm ''if'' hoặc ''whether'' (Do you know if the bank is open?).', '[{"label": "polite opener", "role": "politeness_matrix", "required": true, "examples": ["Could you tell me", "Do you know", "Would you mind telling me"]}, {"label": "Wh-/if + S + V", "role": "embedded_question_statement_order", "required": true, "examples": ["where the conference room is", "if the train leaves on time"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:indirect-polite-questions' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT 'd089e6ad-6d61-5477-843d-282f5edcbbd4', c.id, 'S + must / might / could / can''t + base verb', 'modality', 'Express how certain or uncertain you are about a present situation based on evidence.', 'Khi suy đoán ở hiện tại: dùng ''must + V'' khi chắc chắn đúng (90%); dùng ''might/could + V'' khi có khả năng (50%); dùng ''can''t + V'' khi chắc chắn KHÔNG thể đúng.', 'Khi phủ định một suy đoán chắc chắn, phải dùng ''can''t be'' chứ KHÔNG dùng ''mustn''t be'' (ví dụ: ''He just ate lunch, so he can''t be hungry'').', '[{"label": "epistemic modal", "role": "certainty_degree", "required": true, "examples": ["must", "might", "could", "can''t"]}, {"label": "base verb / be + complement", "role": "inferred_state", "required": true, "examples": ["be in the meeting room", "arrive late because of the rain"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:modal-deduction-must-might' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '4c06f869-03dd-5f97-8481-588665e07c85', c.id, 'S + should/shouldn''t / must / have to / don''t have to + base verb', 'modality', 'Give advice (should) and distinguish strong obligation (must/have to) from lack of necessity (don''t have to).', 'Dùng should/shouldn''t để khuyên bảo nhẹ nhàng; dùng must hoặc have to khi bắt buộc phải làm.', 'Cực kỳ lưu ý sự khác nhau giữa ''mustn''t'' (CẤM không được làm) và ''don''t have to'' (KHÔNG CẦN phải làm, làm hay không tùy ý).', '[{"label": "modal / semi-modal", "role": "deontic_force", "required": true, "examples": ["should", "have to", "don''t have to", "mustn''t"]}, {"label": "base verb phrase", "role": "regulated_action", "required": true, "examples": ["confirm the appointment", "pay extra", "bring your passport"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:modals-obligation-advice' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '2ae4115e-a7e6-5010-a4e8-dfb4a269ccf7', c.id, 'S (receiver) + be + past participle (V3/-ed) (+ by agent)', 'voice', 'Focus on the action or the receiver of the action when the doer is unknown, obvious, or less important.', 'Câu bị động luôn cấu tạo bằng ''be (chia theo thì và chủ ngữ) + V3/-ed''. Rất phổ biến trong thông báo công sở, quy trình và tin tức (The meeting was moved to Friday; Tickets can be booked online).', 'Người Việt hay dịch chữ ''được/bị'' sang từ ''get'' trong mọi trường hợp hoặc quên chia động từ ''be'' theo đúng thì (ví dụ nói ''The report sent yesterday'' thay vì ''The report was sent yesterday'').', '[{"label": "patient subject", "role": "affected_entity", "required": true, "examples": ["The schedule", "Your order", "New articles"]}, {"label": "be + V3/-ed", "role": "passive_predicate", "required": true, "examples": ["was updated this morning", "has been confirmed", "are published weekly"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:passive-voice-core' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '1fddf197-a81a-54ee-9413-e689fa1f9df2', c.id, 'S + V2/-ed | S + did not + base verb | Did + S + base verb?', 'tense_aspect', 'Report a completed event or state at a finished time in the past.', 'Câu khẳng định dùng động từ quá khứ V2 hoặc -ed. Câu phủ định và câu hỏi dùng did, còn động từ chính trở về dạng nguyên mẫu. Trạng từ như yesterday hoặc last week thường làm rõ thời điểm đã kết thúc.', 'Không dùng dạng quá khứ của động từ chính sau did/did not; học riêng các động từ bất quy tắc; không dùng quá khứ đơn cho một việc vẫn đang tiếp diễn đến hiện tại.', '[{"label": "S", "role": "subject", "required": true, "examples": ["The train", "we"]}, {"label": "V2/-ed", "role": "completed_past_event", "required": true, "examples": ["arrived", "went"]}, {"label": "finished-time marker", "role": "past_time_context", "required": false, "examples": ["yesterday", "last week"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:past-simple-core' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '679074ce-4d8b-5664-956b-955d20c82a9e', c.id, 'my/your/his/her/its/our/their + noun', 'noun_phrase', 'Show who owns or is connected with a person or thing.', 'Tính từ sở hữu luôn đứng trước danh từ (my bag, her name) và không thay đổi theo số lượng của danh từ theo sau.', 'Không nhầm his (của anh ấy) và her (của cô ấy) theo giới tính của người được sở hữu; không nhầm its (của nó) với it''s (it is).', '[{"label": "possessive", "role": "possessor_determiner", "required": true, "examples": ["my", "your", "her", "our"]}, {"label": "head noun", "role": "possessed_entity", "required": true, "examples": ["name", "phone", "parents"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:possessive-adjectives-basic' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '729f37e9-707c-5035-a710-a172d78cba3a', c.id, 'at + clock time/point | on + day/date/surface | in + month/year/enclosed space', 'prepositional_phrase', 'Locate events in time and objects or people in physical space.', 'Quy tắc từ hẹp đến rộng: AT dùng cho giờ cụ thể/điểm cụ thể (at 7:00, at the bus stop); ON dùng cho ngày/thứ/bề mặt (on Monday, on the table); IN dùng cho buổi/tháng/năm/không gian bao quanh (in the morning, in May, in Hanoi).', 'Không dùng ''in Monday'' (phải là ''on Monday''); nhớ ngoại lệ ''at night'' và ''on the weekend / at the weekend''.', '[{"label": "at / on / in", "role": "spatial_temporal_preposition", "required": true, "examples": ["at", "on", "in"]}, {"label": "time or place NP", "role": "landmark", "required": true, "examples": ["eight o''clock", "Friday", "the kitchen"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:prepositions-time-place' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '288bedcb-a07c-5bce-9251-3753641b7377', c.id, 'S + am/is/are + V-ing', 'tense_aspect', 'Describe actions happening right now or temporary situations around the present.', 'Hiện tại tiếp diễn luôn cần đủ 2 thành phần: động từ to be (am/is/are) chia theo chủ ngữ VÀ động từ chính thêm đuôi -ing.', 'Lỗi phổ biến nhất là dịch từng từ tiếng Việt ''đang làm'' mà bỏ mất am/is/are (ví dụ nói ''I waiting'' thay vì ''I am waiting''), hoặc dùng thì tiếp diễn với các động từ chỉ trạng thái như know, want, need, like.', '[{"label": "S + am/is/are", "role": "progressive_auxiliary", "required": true, "examples": ["I am", "She is", "They are"]}, {"label": "V-ing", "role": "ongoing_activity", "required": true, "examples": ["waiting for the bus", "working today"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:present-continuous-now' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '7f3e00d8-ab9c-51a0-a4d2-391d7050c495', c.id, 'S + have/has + V3/-ed (+ ever/never/already/yet)', 'tense_aspect', 'Connect past experiences or recent actions to the present without specifying an exact past time.', 'Hiện tại hoàn thành (have/has + V3/-ed) diễn tả trải nghiệm tính đến nay (I have visited Hue twice) hoặc việc vừa mới hoàn thành còn kết quả ở hiện tại (I have sent the email).', 'Tuyệt đối KHÔNG dùng Hiện tại hoàn thành với mốc thời gian quá khứ đã khép kín như yesterday, last week, in 2024 (khi có mốc quá khứ cụ thể bắt buộc phải dùng Quá khứ đơn).', '[{"label": "S + have/has", "role": "perfect_auxiliary", "required": true, "examples": ["I have", "She has", "Have you ever"]}, {"label": "past participle (V3/-ed)", "role": "anterior_event", "required": true, "examples": ["met the new manager", "finished the report", "tried this dish"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:present-perfect-experience' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '3d819808-db5f-5eba-a5f5-408424e56dbf', c.id, 'Past Simple (finished time: yesterday/in 2023) vs. Present Perfect (unbounded/up to now: since/for/already)', 'tense_aspect', 'Contrast completed events anchored in a finished past window against states or actions continuing up to now.', 'Dùng Quá khứ đơn khi thời gian đã chấm dứt (I worked there for two years — giờ đã nghỉ); dùng Hiện tại hoàn thành khi hành động/trạng thái vẫn kéo dài đến hiện tại với since + mốc thời gian hoặc for + khoảng thời gian (I have worked here for two years — giờ vẫn đang làm).', 'Nhầm lẫn giữa ''since'' (từ mốc thời gian: since Monday, since 2024) và ''for'' (trong khoảng thời gian: for three days, for two months).', '[{"label": "aspectual verb phrase", "role": "temporal_viewpoint", "required": true, "examples": ["lived in Hue in 2022", "have lived in Hanoi since 2023"]}, {"label": "time frame expression", "role": "bounded_vs_unbounded_time", "required": true, "examples": ["last year", "since March", "for six months"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:present-perfect-vs-past-simple' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '7b0d66fd-0051-56f0-b2a4-d2a46754682d', c.id, 'S + base verb(s/es) | S + do/does not + base verb | Do/Does + S + base verb?', 'tense_aspect', 'Express habits, repeated situations, routines, and general facts.', 'Dùng động từ nguyên mẫu với I/you/we/they; thêm -s hoặc -es với he/she/it trong câu khẳng định. Câu hỏi và phủ định dùng do/does, sau đó động từ chính trở về dạng nguyên mẫu.', 'Không quên -s/-es với chủ ngữ ngôi ba số ít; không giữ -s/-es sau does; không dùng be trước động từ thường chỉ để đánh dấu hiện tại.', '[{"label": "S", "role": "subject", "required": true, "examples": ["I", "he", "the train"]}, {"label": "base verb(s/es)", "role": "habit_or_fact", "required": true, "examples": ["work", "works"]}, {"label": "frequency/time expression", "role": "repetition_context", "required": false, "examples": ["usually", "on Saturdays"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:present-simple-core' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT 'e79ba433-30e5-5ca7-8f4d-b300fe489d5d', c.id, 'many/a few + plural N | much/a little + uncountable N | enough + N | adj + enough', 'noun_phrase', 'Quantify countable and uncountable nouns and state whether a quantity is sufficient.', 'Many và a few đi với danh từ đếm được số nhiều; much và a little đi với danh từ không đếm được; a lot of đi được với cả hai. Từ ''enough'' đứng TRƯỚC danh từ (enough time) nhưng đứng SAU tính từ/trạng từ (fast enough).', 'Người Việt rất hay đặt ''enough'' trước tính từ theo lối dịch từ ''đủ nhanh'' -> ''enough fast'' (sai -> phải là ''fast enough'').', '[{"label": "quantifier", "role": "quantity_expression", "required": true, "examples": ["many", "much", "a few", "enough time", "clear enough"]}, {"label": "target noun / context", "role": "quantified_head", "required": true, "examples": ["questions", "information", "to finish today"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:quantifiers-much-many-enough' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '550783fb-e81f-56ab-9e6b-6858ee7db120', c.id, 'noun + who/that/which + clause', 'relative_clause', 'Identify or add information about a person or thing.', 'Mệnh đề quan hệ đứng ngay sau danh từ mà nó bổ nghĩa. Dùng who cho người, which cho vật, và that thường dùng cho người hoặc vật trong mệnh đề xác định cơ bản.', 'Không đặt mệnh đề quan hệ xa danh từ được bổ nghĩa; tránh lặp đại từ chủ ngữ sau who/that/which khi từ quan hệ đã làm chủ ngữ; chọn who/which phù hợp.', '[{"label": "head noun", "role": "modified_referent", "required": true, "examples": ["the woman", "the ticket"]}, {"label": "who/that/which", "role": "relative_marker", "required": true, "examples": ["who", "that", "which"]}, {"label": "clause", "role": "identifying_information", "required": true, "examples": ["called me", "I bought"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:relative-clauses-basic' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT 'b12bb44c-8728-542e-b86d-ab4790b5aa58', c.id, 'S + said (that) / told + object (that) + backshifted clause | asked + if/Wh- + S + V', 'clause_combining', 'Report what a colleague, friend, or message said without quoting their exact words.', 'Khi tường thuật lại lời nói ở quá khứ (He said / She told me), động từ thường lùi một thì (present -> past, will -> would, can -> could) và trong câu hỏi tường thuật KHÔNG đảo trợ động từ (She asked where the station was).', ' Hai lỗi phổ biến nhất: (1) dùng ''said me'' thay vì ''told me'' hoặc ''said to me''; (2) giữ nguyên đảo ngữ câu hỏi trong lời nói gián tiếp (''He asked where is the office'' -> sai).', '[{"label": "reporting frame", "role": "speech_attribution", "required": true, "examples": ["She told me that", "He said that", "They asked if"]}, {"label": "reported clause", "role": "backshifted_proposition", "required": true, "examples": ["the meeting would start at ten", "we were available on Friday"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:reported-speech-core' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '7f15ceb2-cdd3-52bf-a850-1b21b5f37d64', c.id, 'If + past simple (were/V2), S + would/could + base verb', 'conditional_clause', 'Imagine unreal, unlikely, or hypothetical present/future situations and their consequences.', 'Câu điều kiện loại 2 dùng thì quá khứ giả định ở mệnh đề If và ''would/could + V nguyên mẫu'' ở mệnh đề chính để nói về điều không có thật ở hiện tại hoặc lời khuyên giả định (If I were you, I would...).', 'Không dùng ''will'' trong câu điều kiện loại 2; hiểu rằng động từ quá khứ ở mệnh đề If mang nghĩa giả định ở HIỆN TẠI chứ không phải chuyện đã qua.', '[{"label": "If + past simple", "role": "hypothetical_condition", "required": true, "examples": ["If we had more time", "If I were you"]}, {"label": "S + would/could + V", "role": "imagined_consequence", "required": true, "examples": ["we would take the scenic train", "I would confirm the date early"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:second-conditional-hypothetical' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT 'c8ec9b15-1c7e-5696-9775-59fb10f94976', c.id, 'I/You/He/She/It/We/They + predicate', 'clause_structure', 'Name the speaker, listener, person, thing, or group acting as the clause subject.', 'Đại từ chủ ngữ đứng trước động từ trong câu trần thuật tiếng Anh. Chọn đại từ theo người và số: I, you, he, she, it, we, they; tiếng Anh thường không lược bỏ chủ ngữ như tiếng Việt.', 'Không dùng me/him/her/them ở vị trí chủ ngữ; không bỏ chủ ngữ; it có thể chỉ đồ vật, động vật hoặc chủ ngữ hình thức.', '[{"label": "subject pronoun", "role": "clause_subject", "required": true, "examples": ["I", "she", "they"]}, {"label": "predicate", "role": "subject_information", "required": true, "examples": ["am ready", "works here", "are students"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:subject-pronouns-basic' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT 'eca7d448-ef74-5808-9ff2-a34c6c8bd6c3', c.id, 'S + be + the + adj-est | S + be + the most + adj', 'comparison', 'Identify the item with the highest or lowest degree of a quality within a group.', 'So sánh nhất luôn có ''the'' đứng trước: thêm -est vào tính từ ngắn (the cheapest, the fastest) và dùng ''the most'' trước tính từ dài (the most convenient). Bất quy tắc: good -> the best, bad -> the worst.', 'Không quên mạo từ ''the'' trước tính từ so sánh nhất; dùng giới từ ''in'' cho nơi chốn/tổ chức (the biggest city in Vietnam) và ''of'' cho khoảng thời gian/nhóm (the busiest day of the week).', '[{"label": "the + superlative", "role": "extreme_quality", "required": true, "examples": ["the fastest", "the most comfortable", "the best"]}, {"label": "noun + scope", "role": "compared_domain", "required": true, "examples": ["way to travel in the city", "option of the three"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:superlatives-core' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '3a5d5537-f56c-5990-8750-396eed802c23', c.id, 'There + is/are + noun phrase (+ place)', 'existential_clause', 'Introduce the existence or presence of a person or thing.', 'Dùng there is trước danh từ số ít hoặc không đếm được và there are trước danh từ số nhiều. There trong mẫu này mở đầu câu tồn tại, không mang nghĩa địa điểm ''ở đó''.', 'Không chọn is/are theo từ there; hãy chọn theo danh từ theo sau; không dịch there theo nghĩa ''ở đó'' trong cấu trúc này; dùng any trong nhiều câu hỏi và phủ định.', '[{"label": "there", "role": "existential_marker", "required": true, "examples": ["there"]}, {"label": "is/are", "role": "number_agreement", "required": true, "examples": ["is", "are"]}, {"label": "noun phrase", "role": "introduced_entity", "required": true, "examples": ["a cafe", "two seats"]}, {"label": "place", "role": "location_context", "required": false, "examples": ["near the station"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:there-is-are' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT 'a1e02913-e07c-57a2-bf68-4a31ce6e53f1', c.id, 'When/Before/After/As soon as + present simple, S + will + base verb', 'adverbial_clause', 'Sequence two events in the past or future using time conjunctions.', 'Trong mệnh đề chỉ thời gian ở tương lai bắt đầu bằng when, before, after, as soon as, until, tiếng Anh dùng thì HIỆN TẠI ĐƠN chứ không dùng will.', 'Tránh dịch chữ ''sẽ'' sang ''will'' trong mệnh đề thời gian (không nói ''When I will arrive, I will call you'' -> phải là ''When I arrive, I will call you'').', '[{"label": "time conjunction + clause", "role": "temporal_anchor", "required": true, "examples": ["When the bus arrives", "Before you leave", "As soon as I finish"]}, {"label": "main clause", "role": "sequenced_event", "required": true, "examples": ["I will send you a message", "please check the windows"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:time-clauses-when-before-after' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '72187eb7-6117-575f-831a-2cfe605c3284', c.id, 'S + want(s) / would like + to + base verb | S + would like + noun', 'verb_complementation', 'Express personal desires directly (want) or politely in service/work situations (would like).', 'Cả ''want'' và ''would like'' đều nối với động từ theo sau bằng ''to + V nguyên mẫu''. Trong giao tiếp lịch sự (gọi món, viết email, nhờ vả), ưu tiên dùng ''would like''.', 'Sau ''would like to'' dùng động từ nguyên mẫu (không dùng V-ing); phân biệt ''Do you like tea?'' (bạn có thích trà nói chung không) với ''Would you like some tea?'' (bạn có muốn dùng chút trà ngay bây giờ không).', '[{"label": "S + want / would like", "role": "desire_matrix", "required": true, "examples": ["I would like", "She wants"]}, {"label": "to + base verb / NP", "role": "desired_target", "required": true, "examples": ["to book a room", "a cup of coffee"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:want-would-like-to' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
INSERT INTO public.grammar_specifications (id, concept_id, pattern_formula, syntactic_category, pragmatic_function, vietnamese_explanation, vietnamese_common_traps, structural_slots) SELECT '221e54c4-9db7-56c2-bc2e-c9a337299d8f', c.id, 'Wh-word + do/does/be + S + V?', 'clause_structure', 'Ask for specific information about time, place, person, reason, or manner.', 'Trong câu hỏi có từ để hỏi (What, Where, When, Why, Who, How), trợ động từ (am/is/are hoặc do/does) phải đảo lên trước chủ ngữ.', 'Không giữ nguyên trật tự câu trần thuật khi đặt câu hỏi (tránh nói ''Where you live?'' -> phải là ''Where do you live?'').', '[{"label": "Wh-word", "role": "question_focus", "required": true, "examples": ["Where", "What time", "How much"]}, {"label": "auxiliary + S (+ V)", "role": "inverted_core", "required": true, "examples": ["do you work", "does the bus leave", "is the ticket"]}]'::jsonb FROM public.concepts c WHERE c.language_code = 'en' AND c.canonical_key = 'grammar:wh-questions-basic' ON CONFLICT (concept_id) DO UPDATE SET pattern_formula = EXCLUDED.pattern_formula, syntactic_category = EXCLUDED.syntactic_category, pragmatic_function = EXCLUDED.pragmatic_function, vietnamese_explanation = EXCLUDED.vietnamese_explanation, vietnamese_common_traps = EXCLUDED.vietnamese_common_traps, structural_slots = EXCLUDED.structural_slots;
